PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS users(user_id INTEGER PRIMARY KEY, name TEXT NOT NULL, email TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'user' CHECK(role IN ('user','admin')), age INTEGER, diet_goal TEXT DEFAULT 'Balanced', daily_calorie_target INTEGER DEFAULT 2000 CHECK(daily_calorie_target BETWEEN 800 AND 6000), created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS allergens(allergen_id INTEGER PRIMARY KEY, name TEXT UNIQUE NOT NULL, severity TEXT DEFAULT 'High');
CREATE TABLE IF NOT EXISTS user_allergens(user_id INTEGER REFERENCES users ON DELETE CASCADE, allergen_id INTEGER REFERENCES allergens, PRIMARY KEY(user_id,allergen_id));
CREATE TABLE IF NOT EXISTS cuisines(cuisine_id INTEGER PRIMARY KEY,name TEXT UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS dietary_types(diet_id INTEGER PRIMARY KEY,name TEXT UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS ingredients(ingredient_id INTEGER PRIMARY KEY,name TEXT UNIQUE NOT NULL,category TEXT,unit TEXT DEFAULT 'g',is_common_allergen INTEGER DEFAULT 0 CHECK(is_common_allergen IN (0,1)), flavor TEXT DEFAULT 'savory');
CREATE TABLE IF NOT EXISTS ingredient_allergens(ingredient_id INTEGER REFERENCES ingredients ON DELETE CASCADE,allergen_id INTEGER REFERENCES allergens,PRIMARY KEY(ingredient_id,allergen_id));
CREATE TABLE IF NOT EXISTS recipes(recipe_id INTEGER PRIMARY KEY,title TEXT NOT NULL,description TEXT,instructions TEXT NOT NULL,prep_time_minutes INTEGER DEFAULT 10 CHECK(prep_time_minutes>=0),cook_time_minutes INTEGER DEFAULT 15 CHECK(cook_time_minutes>=0),servings INTEGER NOT NULL CHECK(servings>0),calories_per_serving REAL CHECK(calories_per_serving>0),protein_g REAL DEFAULT 0 CHECK(protein_g>=0),carbs_g REAL DEFAULT 0 CHECK(carbs_g>=0),fat_g REAL DEFAULT 0 CHECK(fat_g>=0),avg_rating REAL DEFAULT 0,total_views INTEGER DEFAULT 0,cuisine_id INTEGER REFERENCES cuisines,diet_id INTEGER REFERENCES dietary_types,created_by INTEGER NOT NULL REFERENCES users,is_approved INTEGER DEFAULT 1,created_at TEXT DEFAULT CURRENT_TIMESTAMP,image TEXT,meal_type TEXT DEFAULT 'Lunch' CHECK(meal_type IN ('Breakfast','Lunch','Dinner')),flavor TEXT DEFAULT 'savory');
CREATE TABLE IF NOT EXISTS recipe_ingredients(recipe_id INTEGER REFERENCES recipes ON DELETE CASCADE,ingredient_id INTEGER REFERENCES ingredients,quantity REAL NOT NULL CHECK(quantity>0),unit TEXT,PRIMARY KEY(recipe_id,ingredient_id));
CREATE TABLE IF NOT EXISTS ratings(user_id INTEGER REFERENCES users ON DELETE CASCADE,recipe_id INTEGER REFERENCES recipes ON DELETE CASCADE,rating_value INTEGER NOT NULL CHECK(rating_value BETWEEN 1 AND 5),review_text TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(user_id,recipe_id));
CREATE TABLE IF NOT EXISTS favorites(user_id INTEGER REFERENCES users ON DELETE CASCADE,recipe_id INTEGER REFERENCES recipes ON DELETE CASCADE,saved_at TEXT DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(user_id,recipe_id));
CREATE TABLE IF NOT EXISTS meal_plans(plan_id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users ON DELETE CASCADE,plan_name TEXT NOT NULL,start_date TEXT NOT NULL,end_date TEXT NOT NULL,is_active INTEGER DEFAULT 1,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS meal_plan_recipes(plan_id INTEGER REFERENCES meal_plans ON DELETE CASCADE,recipe_id INTEGER REFERENCES recipes,meal_date TEXT NOT NULL,meal_type TEXT NOT NULL CHECK(meal_type IN ('Breakfast','Lunch','Dinner')),servings_planned REAL DEFAULT 1 CHECK(servings_planned>0),PRIMARY KEY(plan_id,meal_date,meal_type));
CREATE TABLE IF NOT EXISTS substitutions(ingredient_id_from INTEGER REFERENCES ingredients,ingredient_id_to INTEGER REFERENCES ingredients,similarity_score REAL NOT NULL CHECK(similarity_score BETWEEN 0 AND 1),PRIMARY KEY(ingredient_id_from,ingredient_id_to));
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users ON DELETE CASCADE,expires_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS idx_recipe_ingredient ON recipe_ingredients(ingredient_id);
CREATE INDEX IF NOT EXISTS idx_plan_user ON meal_plans(user_id);
CREATE TRIGGER IF NOT EXISTS rating_insert AFTER INSERT ON ratings BEGIN UPDATE recipes SET avg_rating=(SELECT AVG(rating_value) FROM ratings WHERE recipe_id=NEW.recipe_id) WHERE recipe_id=NEW.recipe_id; END;
CREATE TRIGGER IF NOT EXISTS rating_update AFTER UPDATE ON ratings BEGIN UPDATE recipes SET avg_rating=(SELECT AVG(rating_value) FROM ratings WHERE recipe_id=NEW.recipe_id) WHERE recipe_id=NEW.recipe_id; END;
CREATE TRIGGER IF NOT EXISTS rating_delete AFTER DELETE ON ratings BEGIN UPDATE recipes SET avg_rating=COALESCE((SELECT AVG(rating_value) FROM ratings WHERE recipe_id=OLD.recipe_id),0) WHERE recipe_id=OLD.recipe_id; END;
